sys_script_include.script:
var AllCompaniesList = Class.create();
AllCompaniesList.prototype = {
    initialize: function() {
        // Hardcode the Script Include's own Sys ID as the default location
        this.defaultTable = 'sys_script_include';
        this.defaultSysID = '9c0b15ec83400710f41ca430ceaad3e9'; // Your actual Sys ID
    },

    getCompanyList: function() {
        var companyNames = [];
        var gr = new GlideRecord('core_company');
        gr.addActiveQuery();
        gr.orderBy('name');
        gr.query();
        while (gr.next()) {
            var name = gr.getValue('name');
            if (name) companyNames.push(name.trim());
        }
        return companyNames.map(function(name, index) {
            return (index + 1) + ". " + name;
        }).join('\n');
    },

    /**
     * Saves the list to the default record, clearing old versions first.
     */
    saveListToFile: function() {
        var content = this.getCompanyList();
        var fileName = "Latest_Company_List.txt";

        var grTarget = new GlideRecord(this.defaultTable);
        if (grTarget.get(this.defaultSysID)) {

            // --- SCOPED-FRIENDLY CLEANUP ---
            // Manually delete existing attachments for this record
            var existingAtt = new GlideRecord('sys_attachment');
            existingAtt.addQuery('table_name', this.defaultTable);
            existingAtt.addQuery('table_sys_id', this.defaultSysID);
            existingAtt.query();
            existingAtt.deleteMultiple(); // Efficiently clears the old files

            // --- WRITE NEW ATTACHMENT ---
            var attachment = new GlideSysAttachment();
            var attachID = attachment.write(grTarget, fileName, 'text/plain', content);

            return "Success! Old files cleared. New Sys ID: " + attachID;
        }
        return "Error: Default host record not found.";
    },

    type: 'AllCompaniesList'
};
